#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::{audio::AudioStream,playback_mp4_audio::Mp4AudioReader};
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact,suffix,anchor};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/mp4-dolby-concealed-seek")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn open(c:&serde_json::Value)->Mp4AudioReader<Cursor<Vec<u8>>>{Mp4AudioReader::open_programme(Cursor::new(bytes(c["file"].as_str().unwrap())),Default::default(),0,c["programme"].as_u64().unwrap()as u8).unwrap()}
fn end(c:&serde_json::Value)->(u128,u128){(c["end_num"].as_u64().unwrap()as u128,c["end_den"].as_u64().unwrap()as u128)}
fn target(c:&serde_json::Value)->Duration{Duration::from_nanos(c["target_ns"].as_u64().unwrap())}
#[test]fn complete_concealment_and_independent_native_controls(){for c in cases(){let n=c["file"].as_str().unwrap();let full=collect(&mut open(&c));assert_eq!(full.iter().map(Packet::frames).sum::<usize>(),c["frames"].as_u64().unwrap()as usize);let mut control=Mp4AudioReader::open(Cursor::new(bytes(c["control"].as_str().unwrap())),Default::default()).unwrap();let decoded=collect(&mut control);let stride=c["channels"].as_u64().unwrap()as usize*4;let pcm:Vec<u8>=decoded.iter().flat_map(|p|p.data.iter().copied()).collect();assert_eq!(pcm.len(),4608*stride);assert!(pcm[..1536*stride].iter().any(|b|*b!=0));assert!(pcm[1536*stride..3072*stride].iter().all(|b|*b==0));assert!(pcm[3072*stride..].iter().any(|b|*b!=0));let mut expected=vec![full[0].clone()];for mut p in decoded{p.num=p.num*500+p.den;p.den*=500;expected.push(p);}expected.push(full.last().unwrap().clone());exact(&full,&expected,n);let mut video=fvid::playback_native::NativeReader::software(Cursor::new(bytes(n)),32<<20).unwrap();for _ in 0..6{assert_eq!(video.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(video.read_frame_raw().unwrap().is_none());}}
#[test]fn warm_seek_accepts_concealed_packet_and_restores_native_history(){for c in cases(){let mut r=open(&c);let full=collect(&mut r);let wanted=suffix(&full,target(&c),end(&c));let at=r.seek_time(target(&c));exact(&collect(&mut r),&wanted,c["file"].as_str().unwrap());assert_eq!(r.time_of(at),anchor(&wanted,end(&c)));r.seek_to(0);exact(&collect(&mut r),&full,"raw reset");}}
#[test]fn fresh_seek_accepts_concealed_packet_before_description_negotiation(){for c in cases(){let full=collect(&mut open(&c));let wanted=suffix(&full,target(&c),end(&c));let mut r=open(&c);let at=r.seek_time(target(&c));exact(&collect(&mut r),&wanted,c["file"].as_str().unwrap());assert_eq!(r.time_of(at),anchor(&wanted,end(&c)));}}
#[test]fn fresh_worker_accepts_concealed_selected_packet(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){let full=collect(&mut open(&c));let wanted=suffix(&full,target(&c),end(&c));let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let captured=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(Box::new(open(&c)),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:captured}));worker.seek(target(&c));worker.play();ended(&worker,worker.generation());let guard=raw.lock().unwrap();exact(&guard.packets,&wanted,c["file"].as_str().unwrap());assert_eq!(guard.anchors,vec![anchor(&wanted,end(&c))]);}}
